import React from "react";
import PropTypes from "prop-types";

import {
  Button,
  FileInput,
  Label,
  NotificationManager,
  TextArea,
} from "@traveloka/soya-components";

import * as style from "./CommonRule.styles";

class ImportFileModal extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      file: {},
      releaseNotes: "",
    };
  }

  render() {
    return (
      <div>
        <div>
          <Label>File</Label>
          <FileInput
            name="file"
            value=""
            description="Choose a .json file"
            onChange={this.handleFileChange}
          />
          <Label>Release Notes</Label>
          <TextArea
            onChange={this.handleInputChange}
            name="releaseNotes"
            placeholder=""
            theme="default"
            marginBottom="sm"
          />
        </div>
        <div className={style.modalFooter}>
          <Button onClick={this.handleCancel} color="link">
            Cancel
          </Button>
          <Button onClick={this.handleSave} color="blue">
            Import
          </Button>
        </div>
      </div>
    );
  }

  handleInputChange = (value) => {
    this.setState({ releaseNotes: value });
  };

  handleFileChange = (value) => {
    if (value[0]) {
      this.setState({ file: value[0] });
    }
  };

  handleCancel = () => {
    const { onCancel } = this.props;
    onCancel();
  };

  handleSave = () => {
    const { onSave } = this.props;
    const { file, releaseNotes } = this.state;
    if (file.name && releaseNotes) {
      const fileExtension = file.name.substring(file.name.lastIndexOf("."));
      if (fileExtension.toLowerCase().trim() === ".json") {
        onSave(file, releaseNotes);
      } else {
        NotificationManager.showError("File must be a json");
      }
    } else {
      NotificationManager.showError("Please fix input");
    }
  };
}

ImportFileModal.propTypes = {
  onSave: PropTypes.func,
  onCancel: PropTypes.func,
};

export default ImportFileModal;
